using Alba;
using Allocation.Contracts;
using Allocation.Slices.Allocation;
using Shouldly;
using Xunit;

namespace Allocation.IntegrationTests.Slices.Allocation;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation — which is the only reason
/// these tests mean anything. Pattern: state-change. Status: ready.
/// LIVE: this slice is claimed, so every test here must pass.
/// This slice needs backend-agent and frontend-agent, so these are the contract between them.
///
/// EVERY TEST HERE IS SEQUENTIAL, which is what a GWT is — and it means all four pass against a reserver
/// with no concurrency guard whatsoever, including the exhaustion rule. That is not a defect in them; it
/// is why ReserveSlotCrossStreamTests exists and why `architect` asks.
/// </summary>
public sealed class ReserveSlotTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string PoolStream => OpenPoolState.StreamKey(SeedData.PoolId.ToString());
    private static string SlotStream(int n) => ReserveSlotState.StreamKey(SeedData.PoolId, n);

    private static PoolOpened Opened(int capacity) =>
        new(SeedData.PoolId, capacity, SeedData.SeededAt);

    /// <summary>WHEN: the reservation request. The slot number comes back in the response because the
    /// caller could not have known it — the decider chose it.</summary>
    private async Task<ReserveSlotEndpoint.Reserved> Reserve(Guid grantId)
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new ReserveSlot(SeedData.PoolId, grantId))
                .ToUrl($"/pools/{SeedData.PoolId}/reservations");
            x.StatusCodeShouldBe(200);
        });
        return await result.ReadAsJsonAsync<ReserveSlotEndpoint.Reserved>()
               ?? throw new InvalidOperationException("no reservation in the response body");
    }

    // The first reservation takes the lowest slot
    //   GIVEN Pool Opened(capacity=3)
    //   WHEN  ReserveSlot
    //   THEN  Slot Reserved(slotNumber=1)
    [Fact]
    public async Task TheFirstReservationTakesTheLowestSlot()
    {
        await Given(PoolStream, Opened(3));

        var reserved = await Reserve(SeedData.GrantId);

        reserved.SlotNumber.ShouldBe(1);
        (await EventsFor(SlotStream(1))).ShouldHaveSingleItem()
            .ShouldBeOfType<SlotReserved>().GrantId.ShouldBe(SeedData.GrantId);
    }

    // A second reservation takes the next slot
    //   GIVEN Pool Opened(capacity=3), Slot Reserved(slotNumber=1)
    //   WHEN  ReserveSlot
    //   THEN  Slot Reserved(slotNumber=2)
    [Fact]
    public async Task ASecondReservationTakesTheNextSlot()
    {
        await Given(PoolStream, Opened(3));
        await Given(SlotStream(1), new SlotReserved(SeedData.PoolId, 1, SeedData.GrantId, SeedData.SeededAt));

        var reserved = await Reserve(SeedData.AcceptedGrant);

        reserved.SlotNumber.ShouldBe(2);
        (await EventsFor(SlotStream(2))).ShouldHaveSingleItem().ShouldBeOfType<SlotReserved>();
    }

    // A pool with every slot taken refuses a reservation
    //   GIVEN Pool Opened(capacity=1), Slot Reserved(slotNumber=1)
    //   WHEN  ReserveSlot
    //   THEN  error: PoolExhausted
    [Fact]
    public async Task APoolWithEverySlotTakenRefusesAReservation()
    {
        await Given(PoolStream, Opened(1));
        await Given(SlotStream(1), new SlotReserved(SeedData.PoolId, 1, SeedData.GrantId, SeedData.SeededAt));

        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new ReserveSlot(SeedData.PoolId, SeedData.AcceptedGrant))
                .ToUrl($"/pools/{SeedData.PoolId}/reservations");
            x.StatusCodeShouldBe(400);
        });

        (await result.ReadAsTextAsync()).ShouldContain(SlotReservation.PoolExhausted);

        // THE LIMIT HELD ON THE EVENT STORE, not on the view. Slot 2 must not exist — a reserver that
        // walked past capacity would have created it, and the availability row would still look sane
        // because it only counts what it was told about (ANTI-PATTERNS #17).
        (await EventsFor(SlotStream(2))).ShouldBeEmpty();
    }

    // A released slot can be reserved again
    //   GIVEN Pool Opened(capacity=1), Slot Reserved(slotNumber=1), Slot Released(slotNumber=1)
    //   WHEN  ReserveSlot
    //   THEN  Slot Reserved(slotNumber=1)
    [Fact]
    public async Task AReleasedSlotCanBeReservedAgain()
    {
        await Given(PoolStream, Opened(1));
        await Given(SlotStream(1),
            new SlotReserved(SeedData.PoolId, 1, SeedData.GrantId, SeedData.SeededAt),
            new SlotReleased(SeedData.PoolId, 1, SeedData.GrantId, "test", SeedData.SeededAt));

        var reserved = await Reserve(SeedData.AcceptedGrant);

        // THE SCENARIO THAT DECIDES THE MECHANISM. The slot's stream already exists, so a reserver built
        // on a StartStream collision — arm 5 of cross-aggregate-invariant/ — would refuse this for ever.
        // Only a fetch-and-fold on the `Held` flag, which is ch. 36's own ReserveEmailAggregate, passes it.
        reserved.SlotNumber.ShouldBe(1);

        var events = await EventsFor(SlotStream(1));
        events.Length.ShouldBe(3);
        events[2].ShouldBeOfType<SlotReserved>().GrantId.ShouldBe(SeedData.AcceptedGrant);
    }
}
